const lockMedicalReport = `-- name: LockMedicalReport :one
SELECT r.id, r.person_id, r.case_id, r.reference, r.version_no, r.root_report_id,
       r.supersedes_report_id, r.report_type, r.report_subtype, r.issuing_practitioner_id,
       r.issuing_provider_organization_id, r.issued_at, r.valid_from, r.valid_to, r.status,
       r.clinical_summary, r.review_comment, r.reject_reason_code, r.reviewed_by,
       r.reviewed_at, r.submitted_at, r.submitted_by, r.created_at, r.row_version,
       COALESCE(c.sensitivity, 'STANDARD')::text AS case_sensitivity
  FROM health.medical_report r
  LEFT JOIN health.health_case c ON c.tenant_id = r.tenant_id AND c.id = r.case_id
 WHERE r.tenant_id = $1
   AND r.id = $2
   AND ($3::uuid[] IS NULL
        OR r.issuing_provider_organization_id = ANY($3::uuid[]))
   FOR UPDATE OF r
`

type LockMedicalReportParams struct {
	TenantID uuid.UUID
	ID       uuid.UUID
	ScopeIds []uuid.UUID
}

type LockMedicalReportRow struct {
	ID                            uuid.UUID
	PersonID                      uuid.UUID
	CaseID                        uuid.NullUUID
	Reference                     string
	VersionNo                     int32
	RootReportID                  uuid.UUID
	SupersedesReportID            uuid.NullUUID
	ReportType                    string
	ReportSubtype                 *string
	IssuingPractitionerID         uuid.NullUUID
	IssuingProviderOrganizationID uuid.NullUUID
	IssuedAt                      pgtype.Date
	ValidFrom                     pgtype.Date
	ValidTo                       pgtype.Date
	Status                        string
	ClinicalSummary               *string
	ReviewComment                 *string
	RejectReasonCode              *string
	ReviewedBy                    uuid.NullUUID
	ReviewedAt                    *time.Time
	SubmittedAt                   *time.Time
	SubmittedBy                   uuid.NullUUID
	CreatedAt                     time.Time
	RowVersion                    int64
	CaseSensitivity               string
}

// The read every command makes before it writes, so two commands on one report serialise.
// FOR UPDATE OF r, because the left-joined case is read here and not written.
func (q *Queries) LockMedicalReport(ctx context.Context, arg LockMedicalReportParams) (LockMedicalReportRow, error) {
	row := q.db.QueryRow(ctx, lockMedicalReport, arg.TenantID, arg.ID, arg.ScopeIds)
	var i LockMedicalReportRow
	err := row.Scan(
		&i.ID,
		&i.PersonID,
		&i.CaseID,
		&i.Reference,
		&i.VersionNo,
		&i.RootReportID,
		&i.SupersedesReportID,
		&i.ReportType,
		&i.ReportSubtype,
		&i.IssuingPractitionerID,
		&i.IssuingProviderOrganizationID,
		&i.IssuedAt,
		&i.ValidFrom,
		&i.ValidTo,
		&i.Status,
		&i.ClinicalSummary,
		&i.ReviewComment,
		&i.RejectReasonCode,
		&i.ReviewedBy,
		&i.ReviewedAt,
		&i.SubmittedAt,
		&i.SubmittedBy,
		&i.CreatedAt,
		&i.RowVersion,
		&i.CaseSensitivity,
	)
	return i, err
}

